from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[1];HOME=R.parents[1];BASE=HOME.parents[1]
def sha(raw):return hashlib.sha256(raw).hexdigest()
def emit(name,obj):(R/name).write_text(json.dumps(obj,indent=2)+'\n',encoding='utf-8')
def canonical(c):return sha(json.dumps({'statement':c['exact_statement'],'hypotheses':c['hypotheses']},sort_keys=True,separators=(',',':')).encode())
checks={}
for f in ['pilot','checks','trees','review_release']:
 checks[f]=json.loads((R/f'out/{f}.json').read_text(encoding='utf-8'));assert checks[f]['result']=='ALL PASS'
old=json.loads((HOME/'runs/20261014T012909Z-account05-A056-balanced-composition/CLAIMS.json').read_text(encoding='utf-8'))[0]
statement=old['exact_statement']+' Additional history closure: choose branch-compatible controller spectra on every reference-only exclusive branch data fiber. For every actual physical query and every finite adaptive data/controller stopping tree, propagate each branch seed by its own actual physical coherent Bayes kernel and normalize, then calibrate each reached shared-only atom. The reached rebuilt mux reference equals categorical calibration of the inherited root Bayes reference at all shared-only controller/data singleton atoms and the two exclusive branch sector totals, preserving conditional complement reference laws. If E is conditional spectral erasure KL release, O is fair/reference physical-outcome KL, and C is categorical calibration savings, D(P_root||Q_root)=sum_internal w(E+O+average C)+E_leaf D(P_leaf||Q_leaf). All terms are nonnegative and references carry one original bank; no fresh conditional core reference is inserted. This proves history compatibility, not influence payment of initial collision entropy, signed entropy decrements, or universal seed costs.'
hyp=old['hypotheses']+['For the new closure choose the exclusive branch controller law at root zero data fibers and the owner coherence kernel at zero physical-controller fibers','Branch complement conditional reference laws are physically transported and retained; arbitrary freshly projected product/occupancy references are excluded','Finite actual adaptive coordinate queries and fair physical child weights; all seed normalization, calibration and outcome terms retained']
c={'claim_id':old['claim_id'],'version':3,'exact_statement':statement,'hypotheses':hyp,'statement_sha256':'','contributors':['account05/A056'],'proof_source':{'path':str(R/'PROOF.md'),'retained_v2':old['proof_source']},'proof_dependencies':[{'claim_id':old['claim_id'],'version':2,'role':'retained local entropy/seed cost and earlier disjoint assertions; structural history closure directly proved'}],'review_records':[],'status':'PROVED_LOCALLY_PENDING_INDEPENDENT_REVIEW','supersedes':[{'claim_id':old['claim_id'],'version':2}],'refutes':[],'first_unproved_line':None,'next_consumers':['A091','A090','A057','A058','A059','A039','A038','A064','A097','A094','B12','B20']}
c['statement_sha256']=canonical(c)
src=BASE/'agents/A057/runs/20261014T015740Z-account05-A057-coherent-restriction-remainder'
author=json.loads((src/'CLAIMS.json').read_text(encoding='utf-8-sig'))
reviewed=next(v for v in author if v['claim_id']=='A057-INTERLEAVED-SELECTOR-RESERVE')
assert canonical(reviewed)==reviewed['statement_sha256']
review={'reviewer':'A056','verdict':'ACCEPT_SECTION1_RELEASE_AND_TELESCOPE_WITHOUT_REPAIR_ONLY','scope':'PROOF Section1: R data release, nonnegative sharp controller release<=2Inf and physical stopped telescope. NOT full cap/signed-entropy/terminal statement.','source':str(R/'REVIEW_A057_SECTION1.md'),'validation':str(R/'out/review_release.json'),'independence':'Separate edge-mismatch and binary-entropy-chord reconstruction; no cap premise used. A056 upstream authorship prevents claiming full cap-chain independent acceptance.'}
reviewed['review_records']=reviewed['review_records']+[review];reviewed['status']='SECTION1_INDEPENDENTLY_ACCEPTED_ONLY_REMAINDER_OUTSIDE_REVIEW'
emit('CLAIMS.json',[c,reviewed]);emit('out/REVIEW_RECORD.json',review)
progress={'protocol_revision':'2026-10-11-execution-v2','run_id':R.name,'stream':'B12','packet_id':'A056','gap_id':'FEI-B12-COMMON-CONTROL-TERMINAL-TRANSPORT','attempt_id':'A056-stage5-carried-calibration-1','method':'Existing candidate repair/closure under physical Bayes transport; branch-compatible zero-fiber completion; exact categorical equality and all adaptive history telescope; independent scoped A057 Section1 review','mathematical_delta':'Inherited-to-rebuilt compatible mux references now close under all physical data/controller restrictions for arbitrary shared width/bias: reset decreases child CE by categorical KL and one root debt telescopes to complete terminals. Essential-query witness refutes categorical-only closure for the old zero-fiber completion; previous local CE theorem unaffected.','deliverable_status':'COMPLETE_LOCAL; supervisor mirror and downstream adoption unobserved','mathematical_status':'C024_COMPATIBLE_HISTORY_CLOSURE_PROVED_LOCAL_REVIEW_PENDING; SOURCE_SECTION1_ACCEPTED; FULL_FEI_OPEN','claim_versions_used':[{'claim_id':old['claim_id'],'version':2,'role':'productive existing transport candidate repaired/extended in same slot'},{'claim_id':reviewed['claim_id'],'version':1,'role':'independent Section1 review only; not premise of new reference closure'}],'claims_created_or_changed':[{'claim_id':c['claim_id'],'version':3},{'claim_id':reviewed['claim_id'],'version':1,'local_change':'source-bound scoped review record; author/shared registries unchanged'}],'source_artifacts':['REPORT.md','PROOF.md','REVIEW_A057_SECTION1.md','SPEC.json','out/TREE_SPEC.json','out/REVIEW_SPEC.json','code/check.py','code/trees.py','code/review_release.py','out/pilot.json','out/checks.json','out/trees.json','out/review_release.json','out/REVIEW_RECORD.json','out/SOURCE_RECEIPTS.json','out/PERSISTENCE.json'],'next_consumers':c['next_consumers'],'next_action':'Pay the exact signed rare/rare mux entropy excess with carried compatible references from one genuinely unused certified terminal-child surplus, keeping both seed bills and destroyed-edge influence debits; A091/A090 review v3.','stagnant_substantive_attempts':0,'blockers':['Initial shared-row entropy excess and universal terminal reference costs remain unpaid','No general selected rare/rare signed entropy payment from certified unused core surplus','New v3 structural history proof pending independent reconstruction; source review accepted only Section1'],'packet_ids':['A056']}
emit('PROGRESS.json',progress);emit('PACKET_DELTA.json',progress)
protocol=Path('~/mop_fei100/reports/fei-2026-10-11/EXECUTION_PROTOCOL.json')
rules=json.loads(protocol.read_text(encoding='utf-8-sig'))['required_per_run']
assert set(progress)=={s.split(' (')[0] for s in rules['progress_fields']}
for cc in [c,reviewed]:assert set(cc)==set(rules['claim_fields']) and canonical(cc)==cc['statement_sha256']
assert (R/'PROGRESS.json').read_bytes()==(R/'PACKET_DELTA.json').read_bytes()
report=(R/'REPORT.md').read_text(encoding='utf-8');assert all('# '+s in report for s in rules['report_fields'])
assert report.split('\n# ')[-1].startswith('Universal bridge\n')
paths=[protocol,BASE/'BOARD.md',BASE/'claude/B12/STREAM_NOTES.md',src/'PROOF.md',src/'CLAIMS.json',BASE/'agents/A039/runs/20261014T025407Z-account05-A039-projection-under-restrictions/PROOF.md',BASE/'agents/A097/runs/20261014T021008Z-account05-A097-cross-route-transfer/DERIVATION.md',BASE/'agents/A058/runs/20261014T022937Z-account05-A058-overlapping-compositions/REPORT.md',HOME/'runs/20261014T012909Z-account05-A056-balanced-composition/DERIVATION.md',HOME/'runs/20261014T012909Z-account05-A056-balanced-composition/CLAIMS.json']
