with (HOME/'LEARNED.md').open('a',encoding='utf-8') as f:f.write('\nStage5 durable facts: Specify Q(U,T)=chat(U)^2 RG(T) on every exclusiveG data fiber, including actual coefficient zero, and analogousH; shared-only root atoms are actual P. With structural zero-fiber physical kernels, rebuilt child mux reference equals categorical calibration of inherited Bayes reference at shared singleton atoms plus exclusiveG/H totals. Thus rootKL=sum w(erasureKL+outcomeKL+mean categorical savings)+mean terminalKL for arbitrary shared width/bias and physical interleaving. This is source-compatible closure, not a root entropy bound. Old empty-controller off-support completion: c=(1,0),G=(1,-1,-1,1),H=(-1,-1,1,1), query essential s influence1/2 gives child inherited masses3/8,3/8,1/8,1/8 versus rebuilt1/4each; categorical savings0, remainingKL1-(log2 3)/2. Extra conditional-controller calibration may repair old choice; the example only refutes categorical-only closure. Fresh product/occupancy complement laws are not licensed by the closure. A057 interleaved reserve Section1 has independent scoped acceptance: controller release<=2Inf sharp, with root bank never reinserted; full cap chain not independently reviewed by its upstream author A056.\n')
status=(HOME/'STATUS.md').read_text(encoding='utf-8').splitlines();assert len(status)==2
emit('out/SCHEMA_CHECK.json',{'protocol_fields':'ALL PASS','claim_hashes':'canonical statement+hypotheses VERIFIED','packet_delta':'BYTE IDENTICAL','rolling_status':'TWO LINES','Universal_bridge':'FINAL PARAGRAPH'})
files=[]
for p in sorted(R.rglob('*')):
 if p.is_file() and p.name!='PERSISTENCE.json':
  raw=p.read_bytes();assert len(raw)<20_000_000;files.append({'path':str(p.relative_to(R)),'bytes':len(raw),'sha256':sha(raw)})
emit('out/PERSISTENCE.json',{'scope':'local only; mirror and downstream use unobserved','files':files,'checks':checks,'rolling_files':[{'path':str(HOME/name),'sha256':sha((HOME/name).read_bytes())} for name in ['STATUS.md','WORKLOG.md','LEARNED.md']]})
print(json.dumps({'saved':R.name,'claim_version':3,'source_review':'A057 Section1 ONLY accepted','schema':'ALL PASS','files':len(files)},indent=2))
